// 1. Convertimos el string JSON de rawData a un objeto JavaScript
var data = JSON.parse(msg.rawData);
var outputMessages = [];

// 2. Función para convertir de Hexadecimal a Float32 (Big-Endian)
function hexToFloat(hex) {
    if (hex.toLowerCase() === "ffffffff") return ""; // Manejo de lecturas vacías/timeout
    
    var int = parseInt(hex, 16);
    if (int === 0) return 0.0;
    
    var sign = (int >>> 31) ? -1 : 1;
    var exp = (int >>> 23 & 0xff) - 127;
    var mantissa = ((int & 0x7fffff) + 0x800000).toString(2);
    var float32 = 0;
    
    for (var i = 0; i < mantissa.length; i += 1) {
        float32 += parseInt(mantissa[i]) ? Math.pow(2, exp) : 0;
        exp--;
    }
    // Redondear a 4 decimales
    return Math.round(sign * float32 * 10000) / 10000;
}

// 3. Función que trocea el Payload hexadecimal y extrae las 9 variables
function procesarPayload(payloadStr) {
    var out = {};
    
    // Comprobamos que el string exista y tenga el tamaño esperado (74 caracteres)
    if (!payloadStr || payloadStr.length < 74) {
        return out;
    }

    // Descartar el byte inicial del Dragino (01 o 81)
    var dataHex = payloadStr.substring(2);

    // Mapeo del mapa Modbus del NICO según la documentación
    out.n_no3_mg_l = hexToFloat(dataHex.substring(0, 8));
    out.no3_mg_l   = hexToFloat(dataHex.substring(8, 16));
    out.sqi        = hexToFloat(dataHex.substring(16, 24));
    out.ref_a      = hexToFloat(dataHex.substring(24, 32));
    out.ref_b      = hexToFloat(dataHex.substring(32, 40));
    out.ref_c      = hexToFloat(dataHex.substring(40, 48));
    out.ref_d      = hexToFloat(dataHex.substring(48, 56));
    out.n_nox_mg_l = hexToFloat(dataHex.substring(56, 64));
    out.nox_mg_l   = hexToFloat(dataHex.substring(64, 72));

    return out;
}

// 4. Procesamiento de la lectura actual
if (data.Payload && data.time) {
    var mainValues = procesarPayload(data.Payload);
    
    // Añadir métricas del propio gateway (batería y señal)
    if (data.battery !== undefined) mainValues.battery = data.battery;
    if (data.signal !== undefined) mainValues.signal = data.signal;
    
    outputMessages.push({
        msg: {
            ts: new Date(data.time).getTime(),
            values: mainValues
        },
        metadata: metadata,
        msgType: msgType
    });
}

function payloadHistoricoValido(payload) {
    if (!payload || !/^(01|81)[0-9A-Fa-f]{72}$/.test(payload)) {
        return false;
    }

    var datos = payload.substring(2).toUpperCase();

    for (var i = 0; i < 72; i += 8) {
        if (datos.substring(i, i + 8) === "FFFFFFFF") {
            return false;
        }
    }

    return true;
}

// 5. Bucle para procesar datos históricos (si el Dragino perdió cobertura y envía el buffer)
for (var key in data) {
    if (!isNaN(key) && Array.isArray(data[key])) {
        var payloadHistorico = data[key][0];
        var tiempoHistorico = data[key][1];

        if (payloadHistoricoValido(payloadHistorico) && tiempoHistorico) {
            outputMessages.push({
                msg: {
                    ts: new Date(tiempoHistorico).getTime(),
                    values: procesarPayload(payloadHistorico)
                },
                metadata: metadata,
                msgType: msgType
            });
        }
    }
}

return outputMessages;

return outputMessages;

var data;

try {
    data = JSON.parse(msg.rawData);
} catch (e) {
    return false;
}

var p = String(data.Payload || "")
    .replace(/\s/g, "")
    .toUpperCase();

// 1 byte inicial + 9 valores de 4 bytes = 74 caracteres hexadecimales
if (!/^(01|81)[0-9A-F]{72}$/.test(p)) {
    return false;
}

// Descartar si los 9 valores son FFFFFFFF
if (/^(01|81)F{72}$/.test(p)) {
    return false;
}

return true;
